import json
from pathlib import Path
R=Path('/workspace/skill-library')
AFF="Original synthesis/processing recipe; not affiliated with Ableton, Reason, Bitwig, Soundtoys, FabFilter, Eventide or any vendor. Map product devices to generic modules (sampler, noise osc, filter, envelope, LFO, EQ, saturator, compressor, delay, reverb) in any DAW, hardware or Web Audio."
STEADY="Steady pitch: no random pitch wobble or randomised notes; no rapid clicking textures (Matt's preference)."
def S(vid,title,sid,name,goal,pre,inputs,outputs,cons,steps,ver,tags):
    d={"schema_version":"1.0","id":sid,"name":name,"goal":goal,"domain":"cinematic-synth",
       "source":{"kind":"youtube-transcript","video_id":vid,"url":f"https://www.youtube.com/watch?v={vid}","title":title,"transcript":"youtube-provided",
                 "distilled_path":f"distilled/{vid}/agent-skill-{sid}.json","batch":"2026-11-09-morning-hunt"},
       "prerequisites":pre,"inputs":[dict(zip(("name","type","description","required"),i)) for i in inputs],
       "outputs":[dict(zip(("name","type","description"),o)) for o in outputs],
       "constraints":cons+[AFF,STEADY],
       "steps":[{"n":n+1,"action":a,"tool":t,"expect":e} for n,(a,t,e) in enumerate(steps)],
       "verification":ver,"tags":tags+["portable","cinematic-synth"],"curriculum_ids":["curriculum-cinematic-hybrid-synth"],"mcp_resource":f"skill://{sid}"}
    p=R/'distilled'/vid; p.mkdir(parents=True,exist_ok=True)
    (p/f'agent-skill-{sid}.json').write_text(json.dumps(d,indent=2,ensure_ascii=False)+"\n"); print(p/f'agent-skill-{sid}.json')

S("-yzW0DZuo40","How to Use White Noise in Your Music",
 "synth-noise-osc-split-filter-env-air-plus-tuned-noise-layers",
 "Synth-native noise air: noise osc on its own low-pass with a fast envelope for bright attack, shelved tape-noise bed boosted near 6 kHz, +24 st noise layer on bass, envelope-following tuned noise on drums, parallel master noise chain",
 "Add air and 'fidelity' with noise generated or layered inside the patch instead of opening the main filter (which adds unwanted energy). Core recipe: put noise on oscillator 2, route oscillators to separate filters (split routing), low-pass the noise and drive its cutoff from a sharp, fast envelope so it adds only a bright, breathy attack. Supporting layers: a low-shelved tape-noise bed with a bell boost near 6 kHz, sneaked in until barely noticed; a noise sampler on the bass MIDI transposed +24 st with a short decay at about -8 dB; envelope-following narrow-band noise on kick (~5 kHz) and snare (~7 kHz, decorrelated for width); and a parallel master noise chain after the other master FX with slow, unsynced, out-of-phase filter LFOs. Delta vs brightness-and-air variants (start-bright-then-filter, field-recording HPF+exciter): this one makes the air from noise inside the synth/patch and on each element.",
 ["A synth with a noise oscillator (or noise wavetable), two filters with split/parallel routing, and a second envelope","A sampler that can play a noise sample from MIDI; EQ; an envelope-follower or gate-keyed noise source; a delay or noise generator for the master chain","Clean noise sources (white/pink/tape hiss) without crackle or vinyl clicks"],
 [("pad_or_lead_patch","synth patch","Patch whose attack should get brighter without opening the main filter",True),("bass_track","midi+audio","Bass part that can take a parallel noise layer",False),("drum_hits","audio","Kick and snare to receive tuned noise",False),("noise_samples","audio","Tape-hiss / white-noise samples, crackle-free",True)],
 [("air_patch","synth patch","Patch with an envelope-shaped noise attack on its own filter"),("noise_layers","audio","Noise bed, bass noise layer, drum noise and master noise chain, each sitting just below notice")],
 ["Pick hiss without crackle or random clicks; the source notes tape noise can carry random clicks, which Matt dislikes. High-pass or swap the sample if clicks are audible.","Demo levels in the source were exaggerated on purpose; final noise levels should be just noticeable on A/B, not obvious.","Use a low shelf rather than a steep low cut on the noise bed (per the source), then boost a pleasing band near 6 kHz.","Avoid audio-rate or random modulation on the noise layers; slow, steady LFOs only."],
 [("Noise bed: put a long tape-hiss/white-noise sample on its own track and hold one note for the whole section. Add an EQ with a low shelf turned down to clear masking lows (shelf, not a steep low cut), then a smooth bell boost around 6 kHz (the 'brilliance' range) where the noise sounds pleasant.","Sampler + EQ","Noise bed with only a bright, airy top"),
  ("Pull the bed way down, then raise it until you just notice it. A/B: without it the mix should sound 'clinical/lifeless'; with it, a little fidelity comes back.","Fader A/B","Bed is felt more than heard"),
  ("Synth-native air: in the pad/lead patch, turn on oscillator 2 with a noise wave. Set filter routing to split so osc 1 goes to filter 1 and the noise osc goes to filter 2.","Synth osc + filter routing","Noise processed separately from the tonal osc"),
  ("Set filter 2 to low-pass. Give envelope 2 a sharp spike (fast attack, short decay, no sustain) and route it to filter 2 cutoff in the mod matrix. Lower filter 2's base cutoff until the noise is heard only as a bright, breathy attack, not a steady hiss. Turn resonance down.","Filter 2 + env 2 + mod matrix","Brighter attack without opening the main filter"),
  ("Raise the envelope-to-cutoff amount for more punch, and back off the noise osc level so it isn't detectable as noise. Optionally automate the noise level up over a section as a slow, rising energy element.","Mod amount + automation","Attack brightness that can grow across the track"),
  ("Bass noise layer: group the bass chain and add a parallel chain with a white-noise sample in a sampler, fed by the same MIDI. Add a pitch MIDI effect of +24 semitones so the noise sits two octaves up and its colour follows the notes. Set amp envelope sustain to 0 and tune decay to a short burst; mix it at about -8 dB.","Parallel chain + sampler + pitch +24 st","Bass gains a little upper 'oomph' that tracks each note"),
  ("Drums: put an envelope-following tuned-noise device (noise shaped by the input's envelope, narrow band-pass; Erosion-like) on the kick around 5 kHz for snap, and on the snare around 7 kHz. For the snare, switch to decorrelated/wide noise (different L/R) for a stereo burst. The peak level rises, so turn the track down to keep limiter headroom.","Envelope-follower noise / gate-keyed noise","Snappier kick, brighter and wider snare without new samples"),
  ("Master noise: make a parallel rack on the master after the other master FX, with a dry chain and a noise chain. In the noise chain, use a noise generator (e.g. a delay's noise feature) with input at about -40 dB or none. Filter the noise and modulate the two filters with slow, unsynced LFOs set out of phase with each other, plus an optional small resonant hump. Sneak it in.","Parallel master chain + filtered noise + slow LFOs","Gently moving air bed that later EQ doesn't boost"),
  ("Map every noise addition to one mute/macro key and A/B the full mix with and without the noise.","Macro / mute group","Subtle, consistent improvement in perceived fidelity")],
 ["With noise layers muted the mix sounds duller/'clinical'; enabled at final level, the change is subtle but audible.","Pad attack is brighter while the main filter cutoff is unchanged (noise only on filter 2).","No audible crackle/clicks in the noise bed; master noise sits after other master FX.","Bass noise layer sits about 8 dB under the bass and decays quickly (sustain 0)."],
 ["air","noise","brightness","noise-oscillator","filter-envelope","exciter-alternative","layering","mix"])

S("eG0401qU-Pw","Regent shows how to craft low end: 1 kick and 3 subs",
 "short-kick-three-sub-layers-hierarchical-ducking",
 "Low end from one short transient kick + three band-focused sub layers in a ducking hierarchy (sub2 ducks to sub1; sub3 ducks to sub1 and sub2; all duck to a ghost kick), glued with tape saturation, 550 Hz mud cut, mono",
 "Build a moving, glued low end where the kick supplies only the downbeat transient and low-mid punch, and three sub layers (a sine sub sample, a sub tail cut from a bass drum, a long generated sine sub) play groovy patterns in the gaps. Each sub is EQ'd to its own band, driven for warmth, made mono and ducked in a strict hierarchy: all to a ghost kick, sub 2 to sub 1, sub 3 to subs 1 and 2. The sub group and the kick+sub bus are then glued with tape saturation, cut around 550 Hz and made mono. Delta vs bass cluster kick-bass-four-level-lock (one kick, one bass, level matching) and sidechain cluster (per-element duck shapes): this adds a multi-sub priority chain so several subs can overlap rhythmically without stacking.",
 ["A short punchy kick (e.g. a processed 909-style hit) and a silent 'ghost' kick track as the sidechain source","Three sub sources: a sine-ish sub one-shot, a bass-drum hit whose sub tail can be cut out, a sine generator for a long sub","Compressors with external sidechain, EQ, overdrive/drive, tape-style saturation, mono utility"],
 [("kick","audio","Short kick: transient plus low-mid punch, little sub",True),("sub_patterns","midi/audio","Rhythmic patterns for the three subs, placed after the kick",True),("tempo_key","text","Track tempo and key (subs tuned to key)",True)],
 [("low_end_bus","audio","Kick + 3-sub bus that moves rhythmically but stays tight, mono and mud-free")],
 ["Source is club techno/house; for ambient/cinematic use, keep the same hierarchy with a softer kick and sparser sub patterns (the soft-kick gap is not fully closed by this).","Keep the low-end bus mono; cut anything above about 130 Hz on each sub so no mids leak into the low layers.","Use plugin names only as aliases: drum-bus = drive/transient/boom shaper; J37/Saturn = tape saturation."],
 [("Kick: keep it short so it leaves room for the subs. Compress lightly for level control, cut around 550 Hz, boost the lows a little, add overdrive in the mid-highs for crunch, a little drive, and make it mono.","EQ + compressor + overdrive + mono","Punchy, short kick that sets the grid"),
  ("Create a muted ghost kick on every kick hit and use it as the sidechain key for all ducking (so the audible kick can change without breaking the ducking).","Ghost MIDI/audio track","Stable sidechain source"),
  ("Sub 1 (master sub): a sine-like sub sample. Remove mids and highs, dip the extreme lows below about 20 Hz, keep roughly 30–100 Hz with a slope after. Add overdrive, drive and tape-style compression for harmonic warmth, make it mono, duck it to the ghost kick, then a final low-pass around 130 Hz.","EQ + drive + tape comp + sidechain comp + LPF","Warm, clean master sub that clears for the kick"),
  ("Sub 2 (secondary): cut the sub tail from a bass-drum hit and program a denser, groovier rhythm. Same chain (mid/high cut, overdrive, drive, tape comp, mono), duck to the ghost kick AND to sub 1, add a little make-up gain, then low-pass.","Same chain + 2 sidechains","Sub 2 fills gaps but yields to sub 1"),
  ("Sub 3 (warmth/flow): a long sustained sine sub from a generator. EQ it to focus a little higher, around 130 Hz, clearing room for the other subs. Duck it to the ghost kick, then to sub 1 and to sub 2, so it is lowest in the hierarchy.","Sine generator + EQ + 3 sidechains","Continuous warmth that never masks subs 1–2"),
  ("Sub group: cut around 550 Hz, give the sub band a small boost (the source says \"around the 25 zone\", which reads as about 25 Hz), and keep a little noise/grit if it adds colour. Optionally test a 100% wet tempo delay to find a better sub rhythm, then remove it if it doesn't help. Duck the whole group to the ghost kick with fast attack and a fairly short release so it stays punchy. Make it mono.","Group EQ + sidechain comp + mono","Subs react quickly around each kick"),
  ("Kick+sub bus: add tape saturation to glue kick and subs into one tight sound, cut around 550 Hz again after saturation, and make it mono.","Bus saturation + EQ + mono","Cohesive, thick but not overbearing low end"),
  ("Listen to kick + subs alone: you should already hear a groove, with each sub covering a slightly different part of the low band. Adjust patterns before adding percussion.","Solo low-end bus","Low end grooves on its own")],
 ["On a spectrum view each sub occupies a different low band (sub 3 around 130 Hz, subs 1–2 lower); nothing above about 130 Hz on the sub channels.","With the ghost kick muted the subs stop ducking; with it on, kick transients stay clear.","When sub 1 plays, sub 2 and sub 3 drop in level (the hierarchy works).","The bus collapses to mono with no loss of low end."],
 ["kick","sub-bass","low-end","sidechain","ducking","layering","saturation","bass"])

S("XAch1Q0Iodc","Use this 90s sampling technique for ethereal pads",
 "sampler-loop-chord-scrub-parallel-harmony-pad",
 "90s sampler pad: loop a single bounced synth note in a repitching sampler, play chords so each voice scrubs the loop at its own speed, ping-pong loop, wide voicings, slow filter LFO, then resample the chord and play it again for parallel harmony",
 "Make ethereal 90s-jungle/intelligent-DnB-style pads from one sampled note. A repitching sampler (no time-stretch) plays each chord voice at a different speed, so looped voices drift against each other and overlap into slowly shifting textures. Steps: bounce one sustained synth note, loop it in a sampler with enough polyphony, play chords (hold them long), try ping-pong loop mode, open up voicings (7ths and 9ths an octave up scrub faster), add a slow LFO on filter cutoff, then resample the played chord into a new sampler and play that for parallel-harmony chords. Delta vs granular cluster (grain position/density/freeze engines): no granular engine, just classic sampler repitch + loop-phase drift.",
 ["Any synth for the source note; a sampler with repitch (not warp/stretch) playback, loop modes incl. ping-pong, adjustable polyphony, filter and LFO","Ability to bounce/resample to audio"],
 [("source_note","audio","One sustained synth note (or chord for the parallel-harmony variant)",True),("chords","midi","Chord progression to play, with long held chords",True)],
 [("drift_pad","audio","Looped sampler pad whose voices phase-drift into evolving texture"),("parallel_harmony_sample","audio","Resampled chord for parallel-harmony playing")],
 ["Use repitch/classic sampler playback; time-stretching modes remove the per-voice speed difference that creates the effect.","Movement comes from loop-phase drift and a slow filter LFO, not from pitch modulation; keep the sampler pitch steady.","Use only your own synth recordings, not sampled commercial records."],
 [("Play and bounce one sustained note from a synth pad to audio (for the parallel-harmony variant, bounce a full chord instead).","Synth + bounce","Clean single-note sample"),
  ("Load it into a sampler in repitch mode, set a loop over the sustain, and raise the voice/polyphony count so chords can play.","Sampler loop + voices","Looped note playable polyphonically"),
  ("Play a chord and hold it. Each voice reads the loop at a different speed and pitch, so the loops drift and overlap. The longer you hold, the more the texture varies.","Sampler","Shimmering, slowly changing chord texture"),
  ("Switch the loop to ping-pong so some voices bounce back from the loop end, for more texture variation. Try playing lower on the keyboard for a slower, darker drift.","Loop mode","Different texture per register"),
  ("Shape voicings: keep the roots close together and put 7ths/9ths an octave or more up. Those upper voices scrub much faster, adding motion on top. Optionally move the root down a semitone or tone in a multi-sample map.","Chord voicing","Upper voices move faster than roots"),
  ("Add a slow LFO to the sampler's filter cutoff so the pad breathes; also try transposing the whole sampler for different feels.","Sampler filter + slow LFO","Gently evolving tone colour"),
  ("Resample: bounce the played chord to audio, load it into a new sampler and play it. Each key now plays the whole chord shape (parallel harmony), with the drift texture baked in. Loop and repeat if you want.","Resample + new sampler","Parallel-harmony pad with built-in movement")],
 ["Held chord changes texture over 8+ seconds without any pitch LFO.","Upper chord tones audibly cycle faster than the root.","Resampled chord, played on one key, sounds as the full chord transposed (parallel harmony)."],
 ["pad","sampler","resampling","parallel-harmony","texture","ambient","jungle","loop"])

S("nIGiY1jYgWM","Using Phaser Effects",
 "phaser-pad-four-bar-ramp-inverse-filter-peaks-reverb-mix-counter-automation",
 "Phaser pad depth chain: 12-stage phaser on a slow 4-bar ramp modulator with high resonance, then a delay used as two narrow HP/LP filter peaks moving inversely, then a narrow-band 100%-wet reverb whose mix is automated opposite to the filter peaks",
 "Turn a static, near-mono pad into a wide, whispering, evolving texture with a serial phaser → delay-filter → reverb chain. Phaser theory first: stages are all-pass filters and notches = stages/2; spread 0 = mono/centred, 100 = wide. The pad gets 12 stages and a ramp-up modulator looped once every 4 bars (not a sine/triangle), with resonance pushed high. A delay's two narrow filters (one HP, one LP) are moved in opposite directions by sine LFOs with glide, so two frequency peaks pass each other. Then a 100%-wet reverb, filtered to a narrow band with feedback at 0, has its mix automated opposite to the filter peaks: dry while the peaks are strong, fully wet as they fade. Delta vs pad-phaser cluster (eerie-dreamy phaser-delay-reverb, HP phaser chord pad, nested multi-notch): adds the inverse-moving delay filter peaks and the peak↔reverb-mix counter-automation for front-back plus left-right motion.",
 ["Phaser with stage count, resonance/feedback, spread and an assignable/rhythmic modulator (ramp shape, bar-length cycle)","Delay with filters and LFO/mod matrix (or two modulated band filters on a send)","Reverb that can be 100% wet with a band filter; automation lanes"],
 [("pad","audio/midi","Static, centred pad sound",True),("tempo","number","Session tempo for the 4-bar modulator cycle",True)],
 [("phased_pad","audio","Pad with slow phaser sweep, moving filter peaks and depth that breathes against them")],
 ["Use slow, sub-audio modulation for pads. The source's audio-rate LFO demos (20 Hz to 4.2 kHz on vocals/Rhodes) create detuning/wobble, which Matt dislikes, so leave them out.","Keep time-based and stereo modulation in one processor. Widening twice sounds unnatural, and left-right motion fights filters that are also moving across the stereo field.","Start with few phaser stages and work up; behaviour changes a lot as stages increase."],
 [("Test the phaser basics on the pad: compare 2 stages with 18 (more stages = stronger phasing; notches = stages/2), and spread 0 (mono/centred) with 100 (wide, needs a stereo source). Use a slow rate.","Phaser","Understand stages and spread by ear"),
  ("Set the pad phaser to 12 stages with resonance pushed high. Use a ramp-up (rising) modulator shape instead of sine/triangle, looped once every 4 bars, for a gentle sweeping swell.","Phaser + 4-bar ramp modulator","Slow swelling phase sweep every 4 bars"),
  ("After the phaser, insert a delay used mainly as a filter. Enable two narrow-bandwidth filters, one high-pass and one low-pass, and modulate their cutoffs with sine LFOs of different rates and glide, set in opposite directions (one rising while the other falls). Optionally delay the LFO onset with an envelope so the peaks drift slightly.","Delay filters + 2 LFOs","Two resonant peaks sweeping past each other"),
  ("Keep stereo/time modulation in only one of phaser or delay. If the phaser already spreads the sound, don't also widen in the delay.","Routing discipline","Clear motion, no smeared double-widening"),
  ("Add a reverb as the last insert, 100% wet, band-filtered to a small frequency range that highlights the moving peaks, feedback/regeneration at 0. Expect it to sound too wet at first.","Reverb insert","Spatial presence focused on the peak band"),
  ("Automate: increase the delay's filter-peak amounts during the sweep, and automate the reverb mix in the opposite direction. Fully dry when the filter peaks are strongest, jumping to 100% wet as the peaks move away and fade.","Two automation lanes","Pad moves front-back and left-right"),
  ("Check over 16 bars with a simple drum beat and compare with the dry pad.","Loop check","Pad adds depth and motion without masking the beat")],
 ["The phaser sweep repeats once per 4 bars with a rising shape (no fast wobble).","Two filter peaks can be heard moving in opposite directions.","Reverb mix automation is the mirror of the filter-peak automation (dry at peak, wet at trough).","The dry pad sounds static next to the processed pad, which has audible width and depth."],
 ["phaser","pad","all-pass","stages","delay-filter","reverb-automation","movement","stereo-width"])

S("HnDS1YURJkE","The one bass every producer should know how to make [Ableton Live tutorial]",
 "house-organ-bass-sine-sub-unfiltered-plus-square-fifth-two-octaves-up-lp24-keytrack",
 "Classic house organ bass: unfiltered sine two octaves down for the sub, plus a square two octaves and a fifth above it (+7 st) through a key-tracked LP24 at 30 Hz with 50% envelope, mono, an optional ~8 ms noise transient, and bass-mono below 120 Hz",
 "Build the classic house/garage organ bass (the 'Show Me Love' type) from two oscillators. The sub body is a sine two octaves below the played note (A2 sounds as A0) that bypasses the filter. The overtones come from a square two octaves and a perfect fifth above it (+7 semitones), mixed about 3 dB under, through a 24 dB low-pass with 100% key tracking, cutoff at about 30 Hz and envelope 1 at 50% (sustain about 75%), in mono. Add bite with a very short noise burst driven by envelope 2 (sustain 0, about 3.5 dB decaying to nothing in about 8 ms) instead of turning the square up. Keep the low end mono below about 120 Hz. Delta vs bass cluster (808/sine-hold, Reese, sub/mid split, four punchy archetypes): the defining trait is the fifth-interval overtone oscillator on its own filter over a clean, unfiltered sine sub.",
 ["Two-oscillator synth with sine/triangle and square, octave + semitone tuning, per-osc filter bypass (or two parallel layers), 24 dB low-pass with key tracking, two envelopes, a noise source with modulatable gain, mono mode","Bass-mono / mono-below-crossover utility"],
 [("bass_line","midi","House/garage bass line around A1–A2 (sub then lands near A0–G0)",True)],
 [("organ_bass","synth patch/audio","Punchy organ bass with a strong sine sub and fifth overtones that read on small speakers")],
 ["Keep the fifth exactly +7 semitones with no detune drift or pitch LFO. Unison (about 20%) is optional and acts like chorus.","Don't open the cutoff so far that the square dominates and overpowers the sine fundamental; if you open it, lower the square level.","Keep everything below about 120 Hz mono."],
 [("Osc 1: sine, octave -2, mixer at 0 dB, routed around the filter (filter bypassed for osc 1). A note played at A2 now sounds at A0, the bottom of the sub range.","Osc 1","Deep, clean sine sub"),
  ("Osc 2: square, octave 0, detune/transpose +7 semitones, so it sits a perfect fifth and two octaves above osc 1. Mix it at about -3 dB.","Osc 2","Overtone layer that carries on small speakers"),
  ("Give the whole filter to osc 2: 24 dB/oct low-pass, key tracking 100%, cutoff very low (about 30 Hz), envelope 1 to cutoff at 50%. Set envelope 1 sustain to about 75% and the voice mode to mono.","LP24 + key track + env 1","Vanilla house organ bass: strong sub, subtle fifth on top"),
  ("For more top-end bite, raise the cutoff a little and balance by lowering osc 2. Stop before it just sounds like a square wave.","Cutoff vs osc 2 level","Brighter overtones without losing the sine body"),
  ("Optional transient: route envelope 2 to noise gain at 100%, with sustain 0 and a very fast attack/decay (the source's burst falls from about 3.5 dB to nothing in about 7.7 ms). This adds bite without making the square louder.","Env 2 → noise gain","Perceptible click-free bite on each note"),
  ("Variations: add shape to osc 1 or switch it to triangle for a few bridging harmonics; route envelope 2 to the filter with a slow attack for a flute-like tone. Finish with a bass-mono utility so everything under about 120 Hz stays mono while the top stays wide.","Shape/triangle + bass mono","Personalised patch, mono-safe low end")],
 ["A spectrum shows the sine fundamental two octaves below the played note and a component at +2 oct +7 st.","Muting osc 2 on small speakers makes the bass nearly disappear; unmuting brings it back.","Low end below about 120 Hz is mono; the noise transient is shorter than about 10 ms."],
 ["bass","house","organ-bass","fifth-interval","sine-sub","key-tracking","noise-transient"])

S("VhjJlD0Gck0","Use this 4 step formula to create epic synth pulses in any synth: Serum, Phase Plant, Pigment, Vital",
 "noof-synth-pulse-noise-saw-octave-unison-saw-closed-ladder-env-cutoff-energy-macro",
 "NOOF cinematic synth pulse (Noise, Osc, Osc, Filter): white noise + mono saw + saw an octave up with 5 slightly detuned unison voices, all into a fully closed ladder low-pass opened per note by a fast envelope on an eighth-note MIDI line; automate cutoff as the single energy control",
 "Make a driving film/game synth pulse in any synth with a four-part formula: a white-noise oscillator (a small burst of energy on top), osc A as a plain saw, osc B as a saw one octave up with about 5 unison voices slightly detuned (higher tone and width), and one ladder low-pass with its cutoff all the way down, opened briefly on every note of an eighth-note MIDI line by envelope 2. Then automate one parameter, cutoff, across the track. Low cutoff gives the plain pulse; opening it reveals osc B's width and detune, then the noise burst on top, so a single lane adds or removes energy. Delta vs arrangement cluster's square-osc motor and the filter cluster's velocity→cutoff skill: a layer order chosen so the cutoff reveals width and then noise, giving one-knob energy control.",
 ["Any synth with two oscillators plus noise, unison/detune, a ladder-style low-pass, and an envelope routable to cutoff","Eighth-note (or similar) repeated-note MIDI"],
 [("pulse_midi","midi","Repeated eighth-note line on the root or chord tones",True),("energy_curve","automation","Where the cue should gain or lose energy",False)],
 [("synth_pulse","synth patch/audio","Pumping pulse whose energy is controlled by one cutoff lane")],
 ["Keep unison detune slight; it should add width, not wobble. No pitch LFO.","Keep the noise level low; it should be heard only when the cutoff is opened.","Same formula works across synths; only the programming differs. Use generic saw and noise, no presets."],
 [("Noise: enable a white-noise oscillator at a low level as a small burst of energy on top.","Noise osc","Faint noise layer"),
  ("Osc A: default saw, one voice.","Osc A","Plain saw body"),
  ("Osc B: saw pitched one octave up, slightly detuned against osc A, unison about 5 voices with a little detune spread.","Osc B + unison","Higher, wider, livelier layer"),
  ("Route all three into one ladder low-pass with cutoff fully down. Route envelope 2 (retriggered on each MIDI note) to cutoff with a fast attack and quick decay, so each eighth note opens the filter briefly and it falls straight back.","Ladder LP + env 2","Pumping synth pulse on the eighth-note line"),
  ("Automate cutoff through the cue: low = plain pulse (noise and osc B barely audible); higher = osc B width and detune come through; highest = noise burst power on top. Use this single lane to add or remove energy.","Cutoff automation","One-knob energy shaping that follows the arrangement"),
  ("Check that muting noise or osc B matters a lot at high cutoff and little at low cutoff. Add effects on top only after the core works.","Mute A/B","Layers revealed in order as cutoff rises")],
 ["Each eighth note has a clear filter 'pump' with cutoff at minimum.","Raising cutoff audibly adds width (osc B), then noise sparkle.","A single cutoff automation lane changes the perceived energy of the cue."],
 ["synth-pulse","ostinato","cinematic","noise-oscillator","unison","ladder-filter","filter-envelope","automation"])
